const predictRealValue = (rawFeature: number): number => {
  return tf.tidy(() => {
    const input = tf.tensor2d([[rawFeature]], [1, 1]);
    const normInput = input.sub(inputMin).div(inputMax.sub(inputMin));
    const normPrediction = model.predict(normInput) as tf.Tensor;
    const realPrediction = normPrediction.mul(labelMax.sub(labelMin)).add(labelMin);
    return realPrediction.dataSync()[0];
  });
};
